-- 2026-10-31k: donor backgrounds, batch 1 ("Who they are" on /donors/<slug>) for the top 25 donors (owner's approval,
-- "yes", 31 Oct 2026, including the new tables and the six "Official findings" entries for five donors).
-- Creates public.donor_profiles (one row per donor: key, name, kind, facts as a JSON array, last_checked) and
-- public.donor_profile_slugs (the 41 donor page slugs the 25 profiles cover), and inserts 25 profiles with 172 facts,
-- copied exactly from "donor-profiles-batch1.json", which is not committed; the facts are stored in the file's order
-- (already grouped by label). Every source link was checked by Cowork before the data file was written.
-- Read only for the site, as mp_biography: row level security on with a SELECT policy for everyone; service_role gets
-- SELECT only (owner, 31 Oct 2026); anon and authenticated get nothing; only the owner (postgres) can write.
-- New tables, so there are no existing rows to back up. political_donations is not touched (guarded).
-- Guards (RAISE): 25 profiles, 41 slugs, 172 facts; each profile equals the file exactly; the grants are as above;
-- political_donations unchanged (row count and md5 of its id list before and after).
-- Code that reads it: lib/donor-profile.ts (getDonorProfile), app/donors/[slug]/page.tsx.
-- Undo: 2026-10-31k-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

DO $$ BEGIN
  IF to_regclass('public.donor_profiles') IS NOT NULL OR to_regclass('public.donor_profile_slugs') IS NOT NULL THEN
    RAISE EXCEPTION 'donor_profiles or donor_profile_slugs already exists';
  END IF;
END $$;

CREATE TEMP TABLE pd_before ON COMMIT DROP AS
SELECT count(*) AS n, md5(string_agg(id::text, ',' ORDER BY id)) AS h FROM public.political_donations;

CREATE TABLE public.donor_profiles (
  key text PRIMARY KEY,
  name text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('individual','company','union','society','trust','other')),
  facts jsonb NOT NULL CHECK (jsonb_typeof(facts) = 'array'),
  last_checked date NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.donor_profile_slugs (
  slug text PRIMARY KEY,
  key text NOT NULL REFERENCES public.donor_profiles(key) ON DELETE CASCADE
);
CREATE INDEX donor_profile_slugs_key_idx ON public.donor_profile_slugs (key);

-- Read only exposure (as mp_biography, with service_role limited to SELECT).
ALTER TABLE public.donor_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.donor_profile_slugs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can read donor profiles" ON public.donor_profiles FOR SELECT TO public USING (true);
CREATE POLICY "Anyone can read donor profile slugs" ON public.donor_profile_slugs FOR SELECT TO public USING (true);
REVOKE ALL ON public.donor_profiles, public.donor_profile_slugs FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.donor_profiles, public.donor_profile_slugs TO service_role;

CREATE TEMP TABLE dp_file (key text PRIMARY KEY, name text NOT NULL, kind text NOT NULL, n integer NOT NULL, facts jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO dp_file (key, name, kind, n, facts) VALUES
  ('ben-delo', 'Ben Delo', 'individual', 7, $df$[{"label":"Who they are","text":"Ben Delo is a British cryptocurrency billionaire and Oxford graduate who was one of the founders of the BitMEX cryptocurrency exchange. In April 2026 he was based in Hong Kong.","source":{"title":"The Guardian: British crypto billionaire Ben Delo says he has given £4m to Reform UK (8 Apr 2026)","url":"https://www.theguardian.com/politics/2026/apr/08/british-crypto-billionaire-ben-delo-says-he-has-given-4m-to-reform-uk"}},{"label":"Who they are","text":"He said in April 2026 that he intended to move to the UK, which would allow him to keep donating after a £100,000 cap on donations from British citizens living abroad.","source":{"title":"Decrypt: BitMEX Co-Founder Ben Delo Reveals $5.4M Donation to Farage's Reform UK (9 Apr 2026)","url":"https://decrypt.co/363769/bitmex-co-founder-ben-delo-reveals-5-4m-donation-to-farages-reform-uk"}},{"label":"Business","text":"He helped found BitMEX in 2014 and no longer runs it. Its owner, HDR Global Trading, said in July 2026 that the exchange would close on 23 September 2026 after a strategic review.","source":{"title":"Decrypt: BitMEX Co-Founder Ben Delo Gives Farage's Reform UK Another £4 Million (4 Sep 2026)","url":"https://decrypt.co/377411/bitmex-co-founder-ben-delo-gives-farages-reform-uk-another-4-million"}},{"label":"Business","text":"Companies House lists Ben Peter Delo as a director of the Sheila Coates Foundation since 14 November 2018 and of the London Institute for Mathematical Sciences since 15 September 2025.","source":{"title":"Companies House: Ben Peter DELO appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/rU76gyp4TKcfW-pthrNNiOjs0a0/appointments"}},{"label":"Business","text":"In February 2026 he gave £25 million to the Sheila Coates Foundation, a charity he set up in 2020 to support autistic young people in England, where he is one of seven trustees.","source":{"title":"Civil Society: Cryptocurrency tycoon gives £25m to his autism charity (20 Feb 2026)","url":"https://www.civilsociety.co.uk/news/cryptocurrency-tycoon-gives-25m-to-his-autism-charity.html"}},{"label":"Official findings","text":"In February 2022 he pleaded guilty in a US federal court in New York to one count of violating the Bank Secrecy Act, by wilfully failing to maintain an anti money laundering programme at BitMEX, and agreed to pay a $10 million fine.","source":{"title":"US Attorney's Office, Southern District of New York: Founders of cryptocurrency exchange plead guilty to Bank Secrecy Act violations (24 February 2022)","url":"https://www.justice.gov/usao-sdny/pr/founders-cryptocurrency-exchange-plead-guilty-bank-secrecy-act-violations"}},{"label":"Official findings","text":"In March 2025 President Trump granted him a pardon, along with the two other founders of BitMEX.","source":{"title":"Reuters via The Star: Trump pardoned BitMEX co-founders, White House official says (29 March 2025)","url":"https://www.thestar.com.my/tech/tech-news/2025/03/29/trump-pardoned-bitmex-co-founders-white-house-official-says"}}]$df$::jsonb),
  ('christopher-harborne', 'Christopher Harborne', 'individual', 3, $df$[{"label":"Who they are","text":"Christopher Harborne is a British born businessman who has lived and worked in Thailand for more than two decades, holds joint nationality and uses the Thai name Chakrit Sakunkrit.","source":{"title":"MoneyWeek: Who is Christopher Harborne, crypto billionaire and Reform UK's new mega donor? (12 December 2025)","url":"https://www.moneyweek.com/people/who-is-christopher-harborne-crypto-billionaire-reform-uk-donor"}},{"label":"Business","text":"He registered the aviation fuel company AML Global in Thailand in 2003, and later formed Sherriff Global Group, which trades private planes.","source":{"title":"MoneyWeek: Who is Christopher Harborne, crypto billionaire and Reform UK's new mega donor? (12 December 2025)","url":"https://www.moneyweek.com/people/who-is-christopher-harborne-crypto-billionaire-reform-uk-donor"}},{"label":"Ownership and control","text":"He has investments in Tether, the stablecoin issuer, and the crypto exchange Bitfinex, and is the largest shareholder of the UK defence company Qinetiq.","source":{"title":"City AM: Reform UK receives £9m donation from billionaire businessman Christopher Harborne (4 December 2025)","url":"https://www.cityam.com/?p=2384180"}}]$df$::jsonb),
  ('co-operative-group', 'Co-operative Group Ltd (the Co-op)', 'society', 7, $df$[{"label":"Who they are","text":"Co-operative Group Limited is a registered society under the Co-operative and Community Benefit Societies Act 2014, number 525R, with its registered office at 1 Angel Square, Manchester.","source":{"title":"FCA Mutuals Public Register: Co-operative Group Limited","url":"https://mutuals.fca.org.uk/Search/Society/7240"}},{"label":"Business","text":"The Co-op's businesses include food retail, wholesale, Federal Retail Trading Services, franchise, Life Services and a new commercial and logistics division. It supplies close to 8,000 stores, including more than 2,300 of its own.","source":{"title":"Co-op Group: 2025 Trading Update (26 March 2026)","url":"https://www.investegate.co.uk/announcement/rns/co-operative-group-holdings-2011-limited--46rp/co-op-group-2025-trading-update-/9492482"}},{"label":"Ownership and control","text":"The Co-op says it is owned by its members and was established in 1844 in Rochdale.","source":{"title":"Co-op Group: 2025 Trading Update (26 March 2026)","url":"https://www.investegate.co.uk/announcement/rns/co-operative-group-holdings-2011-limited--46rp/co-op-group-2025-trading-update-/9492482"}},{"label":"Ownership and control","text":"Members vote on its political spending: at the 2018 AGM members approved political expenditure of up to £750,000 for 2019, with 79.38 per cent support, and the Group planned to contribute £625,600 to the Co-operative Party in 2018.","source":{"title":"Co-op News: Co-op Group AGM: voting results (20 May 2018)","url":"https://www.thenews.coop/co-op-group-agm-voting-results/"}},{"label":"Size","text":"Total group revenue was £11,025 million in 2025, down 2.3 per cent on the previous year.","source":{"title":"Co-op Group: 2025 Trading Update (26 March 2026)","url":"https://www.investegate.co.uk/announcement/rns/co-operative-group-holdings-2011-limited--46rp/co-op-group-2025-trading-update-/9492482"}},{"label":"Represents","text":"The Co-op reports 7.2 million active members in 2025, up 17 per cent.","source":{"title":"Co-op Group: 2025 Trading Update (26 March 2026)","url":"https://www.investegate.co.uk/announcement/rns/co-operative-group-holdings-2011-limited--46rp/co-op-group-2025-trading-update-/9492482"}},{"label":"Official findings","text":"In March 2019 the Groceries Code Adjudicator found that the Co-op broke the Groceries Supply Code of Practice by delisting suppliers without reasonable notice and by adding charges without reasonable notice. She made five recommendations and ordered it to pay the cost of the investigation, but did not fine it; the Co-op repaid the suppliers affected.","source":{"title":"GOV.UK: Co-op breached Code, finds Groceries Code Adjudicator (25 March 2019)","url":"https://www.gov.uk/government/news/co-op-breached-code-finds-groceries-code-adjudicator"}}]$df$::jsonb),
  ('communication-workers-union', 'Communication Workers Union', 'union', 5, $df$[{"label":"Who they are","text":"The Communication Workers Union (CWU) is a trade union formed in 1995 by the merger of the Union of Communication Workers and the National Communications Union.","source":{"title":"Wikipedia: Communication Workers Union (United Kingdom)","url":"https://en.wikipedia.org/wiki/Communication_Workers_Union_(United_Kingdom)"}},{"label":"Size","text":"The CWU reported 164,651 members at 31 December 2024 in its annual return to the Certification Officer, of whom 159,563 were in Great Britain. The return gives its head office as 150 The Broadway, Wimbledon, and names Dave Ward as general secretary.","source":{"title":"Certification Officer (GOV.UK): Communication Workers Union 2024 Annual Return (form AR21, year ended 31 December 2024)","url":"https://assets.publishing.service.gov.uk/media/691dab33d140bbbaa59a2a17/CWU_AR21_2024.pdf"}},{"label":"Represents","text":"Its members work in postal delivery, telephone, broadband and technology companies, including Royal Mail, the Post Office, BT, O2 and Sky.","source":{"title":"Wikipedia: Communication Workers Union (United Kingdom)","url":"https://en.wikipedia.org/wiki/Communication_Workers_Union_(United_Kingdom)"}},{"label":"Political fund","text":"In 2024 the CWU's political fund had income of £1,204,320 and spending of £1,957,390, and held £2,141,058 at the end of the year. 112,205 members contributed to the fund.","source":{"title":"Certification Officer (GOV.UK): Communication Workers Union 2024 Annual Return (form AR21, year ended 31 December 2024)","url":"https://assets.publishing.service.gov.uk/media/691dab33d140bbbaa59a2a17/CWU_AR21_2024.pdf"}},{"label":"Political fund","text":"The CWU says it has been affiliated to the Labour Party since the union was formed.","source":{"title":"CWU: CWU and the Labour Party","url":"https://www.cwu.org/about-the-cwu/cwu-in-politics/cwu-and-the-labour-party/"}}]$df$::jsonb),
  ('frank-hester', 'Frank Hester', 'individual', 8, $df$[{"label":"Who they are","text":"Frank Hester is a healthcare technology entrepreneur and computer programmer from Leeds whose company, The Phoenix Partnership (TPP), supplies computer systems to the NHS.","source":{"title":"The Guardian: One of Tories' biggest ever donors profited from £135m of NHS contracts (20 Sep 2023)","url":"https://www.theguardian.com/politics/2023/sep/20/one-of-tories-biggest-ever-donors-frank-hester-profited-from-135m-of-nhs-contracts"}},{"label":"Business","text":"He founded TPP in 1997.","source":{"title":"Yorkshire Post: Leading Leeds businessman Frank Hester donates £5m to the Conservative Party","url":"https://www.yorkshirepost.co.uk/business/leading-leeds-businessman-frank-hester-donates-ps5m-to-the-conservative-party-this-is-why-4282131"}},{"label":"Business","text":"He was a director of The Phoenix Partnership (Leeds) Ltd from 21 February 2001 until he resigned on 5 September 2025. The company's nature of business is software development and information technology consultancy.","source":{"title":"Companies House: THE PHOENIX PARTNERSHIP (LEEDS) LTD people","url":"https://find-and-update.company-information.service.gov.uk/company/04077829/officers"}},{"label":"Ownership and control","text":"Companies House lists Francis Xavier James Hester as the person with significant control of TPP Group Limited, owning 75 per cent or more of its shares and voting rights.","source":{"title":"Companies House: TPP GROUP LIMITED persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/11785575/persons-with-significant-control"}},{"label":"Size","text":"The Phoenix Partnership (Leeds) Ltd reported turnover of £97.1 million in the year to 31 March 2025, almost all of it in the UK, with an average of 76 staff. Its principal activity is the provision of computer software and support to the health sector, and its accounts say it is ultimately controlled by F X J Hester, who owns all of the share capital of its ultimate parent, TPP Group Limited.","source":{"title":"Companies House: The Phoenix Partnership (Leeds) Ltd full accounts made up to 31 March 2025","url":"https://find-and-update.company-information.service.gov.uk/company/04077829/filing-history/MzQ5MTkyNTM3MWFkaXF6a2N4/document?format=pdf&download=0"}},{"label":"Wealth (as reported)","text":"The Guardian reported in September 2023 that the Sunday Times Rich List estimated his wealth at £415 million.","source":{"title":"The Guardian: One of Tories' biggest ever donors profited from £135m of NHS contracts (20 Sep 2023)","url":"https://www.theguardian.com/politics/2023/sep/20/one-of-tories-biggest-ever-donors-frank-hester-profited-from-135m-of-nhs-contracts"}},{"label":"Honours","text":"He was appointed OBE in the 2015 New Year Honours as Founder and Chief Executive Officer of TPP, for services to healthcare.","source":{"title":"GOV.UK: New Year's honours for health and social care (31 Dec 2014)","url":"https://www.gov.uk/government/news/new-years-honours-for-health-and-social-care"}},{"label":"Sector interests","text":"TPP supplies software to about 2,700 GP surgeries in England. The Guardian reported in 2023 that it had £135 million of contracts with the Department of Health and Social Care in under four years and that such contracts appear to make up a large proportion of its business.","source":{"title":"The Guardian: One of Tories' biggest ever donors profited from £135m of NHS contracts (20 Sep 2023)","url":"https://www.theguardian.com/politics/2023/sep/20/one-of-tories-biggest-ever-donors-frank-hester-profited-from-135m-of-nhs-contracts"}}]$df$::jsonb),
  ('gary-lubner', 'Gary Lubner', 'individual', 6, $df$[{"label":"Who they are","text":"Gary Lubner is a South African born businessman, the former chief executive of Belron and the founder of the This Day Foundation.","source":{"title":"Brentford FC: New investment from Gary Lubner and Sir Matthew Vaughn (15 July 2025)","url":"https://www.brentfordfc.com/en/news/article/club-news-brentford-new-investment-gary-lubner-sir-matthew-vaughn"}},{"label":"Business","text":"He was chief executive of Belron, the vehicle glass repair and replacement group that operates in 37 countries, from 2000; Carlos Brito succeeded him in March 2023 and Lubner stayed on Belron's board.","source":{"title":"CollisionWeek: Carlos Brito to succeed Gary Lubner as CEO of Safelite parent Belron (22 November 2022)","url":"https://collisionweek.com/2022/11/22/carlos-brito-succeed-gary-lubner-ceo-safelite-parent-belron/"}},{"label":"Business","text":"His foundation, This Day, funds, advises and supports organisations, campaigns and civic initiatives in the UK and South Africa.","source":{"title":"UCL Policy Lab: Supporting an ecosystem for transformative change, Gary Lubner (28 November 2023)","url":"https://www.ucl.ac.uk/policy-lab/news/2023/nov/supporting-ecosystem-transformative-change-gary-lubner"}},{"label":"Ownership and control","text":"The Telegraph reported in April 2026 that he holds a minority stake of about 3.3 per cent in Belron through the holding company Atessa, and that D'Ieteren Group is Belron's majority owner.","source":{"title":"The Telegraph (via Yahoo Finance): Labour donor in line for €1bn payday from Autoglass listing (16 April 2026)","url":"https://finance.yahoo.com/markets/stocks/articles/labour-donor-line-1bn-payday-182821082.html"}},{"label":"Ownership and control","text":"In July 2025 he became a minority shareholder, through This Day, which he controls, in Best Intentions Analytics, the holding company of Brentford FC.","source":{"title":"Brentford FC: New investment from Gary Lubner and Sir Matthew Vaughn (15 July 2025)","url":"https://www.brentfordfc.com/en/news/article/club-news-brentford-new-investment-gary-lubner-sir-matthew-vaughn"}},{"label":"Wealth (as reported)","text":"The Telegraph reported in April 2026 that he stood to make at least €1bn (£870m) from Belron's planned listing on the Amsterdam stock exchange.","source":{"title":"The Telegraph (via Yahoo Finance): Labour donor in line for €1bn payday from Autoglass listing (16 April 2026)","url":"https://finance.yahoo.com/markets/stocks/articles/labour-donor-line-1bn-payday-182821082.html"}}]$df$::jsonb),
  ('gmb', 'GMB', 'union', 5, $df$[{"label":"Who they are","text":"GMB is a general trade union founded in March 1889 at the Beckton Gas Works in East London.","source":{"title":"GMB: About","url":"https://www.gmb.org.uk/about"}},{"label":"Size","text":"GMB reported 534,418 members at 31 December 2025 in its annual return to the Certification Officer, of whom 524,415 were in Great Britain. The return names Gary Smith as general secretary.","source":{"title":"Certification Officer (GOV.UK): GMB Annual Return 2025 (form AR21, year ended 31 December 2025)","url":"https://assets.publishing.service.gov.uk/media/6a7c6771114277b327805cb5/AR21_2025.pdf"}},{"label":"Represents","text":"GMB describes itself as a union for all workers, with members in public services such as the NHS and ambulance services, local government and the civil service, and in private sector industries such as energy, aviation, and retail and distribution.","source":{"title":"GMB: About","url":"https://www.gmb.org.uk/about"}},{"label":"Political fund","text":"In 2025 GMB's political fund had income of £1.390 million and spending of £1.281 million, and held £576,000 at the end of the year. 288,325 members contributed to the fund.","source":{"title":"Certification Officer (GOV.UK): GMB Annual Return 2025 (form AR21, year ended 31 December 2025)","url":"https://assets.publishing.service.gov.uk/media/6a7c6771114277b327805cb5/AR21_2025.pdf"}},{"label":"Political fund","text":"GMB is one of the 11 trade unions affiliated to the Labour Party.","source":{"title":"The Labour Party: Affiliated Unions","url":"https://labour.org.uk/people/unions/"}}]$df$::jsonb),
  ('graham-edwards', 'Graham Edwards', 'individual', 8, $df$[{"label":"Who they are","text":"Graham Edwards is a property businessman whom The Guardian described in December 2022 as executive chair of Telereal Trillium, one of the UK's largest property firms.","source":{"title":"The Guardian: Tories make billionaire ex-Mubarak minister senior treasurer (14 December 2022)","url":"https://www.theguardian.com/politics/2022/dec/14/tories-billionaire-murbarak-minister-mohamed-mansour-party-senior-treasurer-mohamed-mansour-egypt"}},{"label":"Business","text":"He was chief executive of Telereal from its creation in 2001 and became executive chairman of TT Group in 2018; Telereal began with a £2.4bn deal that transferred 6,700 properties from BT. Earlier he was a fund manager at Merrill Lynch Investment Management and head of finance for BT's property department.","source":{"title":"TT Group: Meet the team, Graham Edwards","url":"https://www.ttg.co.uk/meet-the-team/graham-edwards"}},{"label":"Business","text":"Companies House lists Graham Henry Edwards as a director of Castle Water Limited since April 2014 (nature of business: water collection, treatment and supply), and of Centre for Policy Studies Limited since July 2020.","source":{"title":"Companies House: Graham Henry EDWARDS appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/296Yt1zhuoRIaU-ZifngSkupppQ/appointments"}},{"label":"Ownership and control","text":"He is a director and shareholder of Castle Water.","source":{"title":"The Water Report: Castle Water director Graham Edwards appointed Conservative Party treasurer (18 December 2022)","url":"https://www.thewaterreport.co.uk/single-post/castle-water-director-graham-edwards-appointed-conservative-party-treasurer"}},{"label":"Ownership and control","text":"ITV News reported in November 2025 that Castle Water is part owned by him.","source":{"title":"ITV News: Castle Water vows to create 2,000 jobs at Thames Water in fresh bid approach (17 November 2025)","url":"https://www.itv.com/news/meridian/2025-11-17/castle-water-vows-to-create-2000-jobs-at-thames-water-in-fresh-bid-approach"}},{"label":"Public roles","text":"He was appointed treasurer of the Conservative Party in December 2022.","source":{"title":"The Water Report: Castle Water director Graham Edwards appointed Conservative Party treasurer (18 December 2022)","url":"https://www.thewaterreport.co.uk/single-post/castle-water-director-graham-edwards-appointed-conservative-party-treasurer"}},{"label":"Public roles","text":"ITV News still described him as Conservative Party treasurer in November 2025.","source":{"title":"ITV News: Castle Water vows to create 2,000 jobs at Thames Water in fresh bid approach (17 November 2025)","url":"https://www.itv.com/news/meridian/2025-11-17/castle-water-vows-to-create-2000-jobs-at-thames-water-in-fresh-bid-approach"}},{"label":"Sector interests","text":"In 2025 Castle Water, which describes itself as the largest independent water retailer in the UK, made approaches to take over Thames Water.","source":{"title":"ITV News: Castle Water vows to create 2,000 jobs at Thames Water in fresh bid approach (17 November 2025)","url":"https://www.itv.com/news/meridian/2025-11-17/castle-water-vows-to-create-2000-jobs-at-thames-water-in-fresh-bid-approach"}}]$df$::jsonb),
  ('ipgl', 'IPGL Ltd', 'company', 9, $df$[{"label":"Who they are","text":"IPGL Limited is a private limited company, number 02011009, incorporated on 16 April 1986 as Inter Capital Brokers Limited and registered in Knightsbridge, London. It took its present name in 2005.","source":{"title":"Companies House: IPGL LIMITED (02011009) overview","url":"https://find-and-update.company-information.service.gov.uk/company/02011009"}},{"label":"Business","text":"Its principal activity is making strategic investments: it holds minority and majority stakes in a portfolio mainly of operating businesses, some of them listed.","source":{"title":"Companies House: IPGL Limited report and financial statements for the year ended 31 March 2025 (filed 7 January 2026)","url":"https://find-and-update.company-information.service.gov.uk/company/02011009/filing-history/MzQ5NzQ4Nzk1MWFkaXF6a2N4/document?format=pdf&download=0"}},{"label":"Ownership and control","text":"Companies House lists IPGL (Holdings) Limited as its person with significant control, holding 75 per cent or more of its shares and votes.","source":{"title":"Companies House: IPGL LIMITED persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/02011009/persons-with-significant-control"}},{"label":"Ownership and control","text":"Companies House lists Michael Alan Spencer, Lord Spencer of Alresford, as a person with significant control of IPGL (Holdings) Limited with 75 per cent or more of the shares and votes, and Lady Lorraine Geraldine Spencer and David Jeremy Courtenay-Stamp each with more than 25 but not more than 50 per cent.","source":{"title":"Companies House: IPGL (HOLDINGS) LIMITED persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/09064598/persons-with-significant-control"}},{"label":"Ownership and control","text":"Lord Spencer of Alresford has been a director since before 1992. Other directors include Thomas George Spencer and David Jeremy Courtenay-Stamp.","source":{"title":"Companies House: IPGL LIMITED officers","url":"https://find-and-update.company-information.service.gov.uk/company/02011009/officers"}},{"label":"Size","text":"At 31 March 2025 the company had net assets of £980.7 million and made a loss of £44.9 million for the year.","source":{"title":"Companies House: IPGL Limited report and financial statements for the year ended 31 March 2025 (filed 7 January 2026)","url":"https://find-and-update.company-information.service.gov.uk/company/02011009/filing-history/MzQ5NzQ4Nzk1MWFkaXF6a2N4/document?format=pdf&download=0"}},{"label":"Public roles","text":"Lord Spencer of Alresford founded the brokerage Intercapital in 1986, later led ICAP as chief executive, and is a board director of CME Group. He was Conservative Party Treasurer from 2007 to 2010.","source":{"title":"House of Lords Appointments Commission: Michael Spencer citation","url":"https://lordsappointments.independent.gov.uk/wp-content/uploads/2025/04/Michael-Spencer-citation.docx.pdf"}},{"label":"Public roles","text":"Lord Spencer of Alresford has been a Conservative member of the House of Lords since 17 September 2020.","source":{"title":"UK Parliament: Lord Spencer of Alresford","url":"https://members.parliament.uk/member/4892"}},{"label":"Sector interests","text":"Lord Spencer's register of interests lists him as a director of IPGL Limited, a holding company of a trading group, and lists shareholdings held by IPGL Limited in companies including CME Group, AJ Bell, Klarna, National Grid, Gamma Communications, UK Tote Group, Conduit Holdings and Helios Underwriting.","source":{"title":"UK Parliament: Lord Spencer of Alresford, registered interests","url":"https://members.parliament.uk/member/4892/registeredinterests"}}]$df$::jsonb),
  ('jcb', 'JCB', 'company', 12, $df$[{"label":"Who they are","text":"JCB is a machinery maker controlled by the Bamford family. J.C. Bamford Excavators Limited (00561597) is a wholly owned subsidiary of J.C.B. Service (00564955), and the largest group to consolidate it is JCB Group Holdings Sarl of Lausanne, Switzerland, which its accounts say is ultimately controlled by Bamford family interests.","source":{"title":"Companies House: J.C. Bamford Excavators Limited directors' report and financial statements for the year ended 31 December 2025 (filed 2 October 2026)","url":"https://find-and-update.company-information.service.gov.uk/company/00561597/filing-history/MzU0ODMzNjA3MmFkaXF6a2N4/document?format=pdf&download=0"}},{"label":"Business","text":"The principal activity of J.C. Bamford Excavators Limited is the design, manufacture, marketing and sale of machines primarily for the construction industry.","source":{"title":"Companies House: J.C. Bamford Excavators Limited directors' report and financial statements for the year ended 31 December 2025 (filed 2 October 2026)","url":"https://find-and-update.company-information.service.gov.uk/company/00561597/filing-history/MzU0ODMzNjA3MmFkaXF6a2N4/document?format=pdf&download=0"}},{"label":"Business","text":"J.C.B. Research (00682651) is a private unlimited company incorporated on 6 February 1961, registered at Lakeside Works, Rocester, Uttoxeter, the same address as the other JCB companies, with its nature of business listed as manufacture of earthmoving equipment.","source":{"title":"Companies House: J.C.B.RESEARCH (00682651) overview","url":"https://find-and-update.company-information.service.gov.uk/company/00682651"}},{"label":"Ownership and control","text":"Companies House lists Peter Haqvin Erland Svennilson as the person with significant control of J.C.B. Service since 1 January 2025, holding 75 per cent or more of its shares and votes through control over the trustees of a trust. Patrick Albert Michaël Fischer held that position from 2016 to 2025.","source":{"title":"Companies House: J.C.B. SERVICE persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/00564955/persons-with-significant-control"}},{"label":"Ownership and control","text":"Companies House lists Anthony Paul, Lord Bamford, as the person with significant control of J.C.B. Research, holding 75 per cent or more of its shares and votes.","source":{"title":"Companies House: J.C.B.RESEARCH persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/00682651/persons-with-significant-control"}},{"label":"Ownership and control","text":"The directors of J.C.B. Service include Lord Bamford, Lady Bamford, George Bamford, Joseph Cyril Edward Bamford and Alice Bamford.","source":{"title":"Companies House: J.C.B. SERVICE officers","url":"https://find-and-update.company-information.service.gov.uk/company/00564955/officers"}},{"label":"Ownership and control","text":"George Bamford, the younger son of Lord Bamford, was appointed joint chairman of JCB in September 2026, alongside his father.","source":{"title":"The Construction Index: George Bamford appointed joint chairman of JCB (28 September 2026)","url":"https://www.theconstructionindex.co.uk/news/view/george-bamford-appointed-joint-chairman-of-jcb"}},{"label":"Size","text":"J.C. Bamford Excavators Limited had turnover of £1,707.8 million in 2025 (2024: £1,991.4 million) and an average of 3,413 employees.","source":{"title":"Companies House: J.C. Bamford Excavators Limited directors' report and financial statements for the year ended 31 December 2025 (filed 2 October 2026)","url":"https://find-and-update.company-information.service.gov.uk/company/00561597/filing-history/MzU0ODMzNjA3MmFkaXF6a2N4/document?format=pdf&download=0"}},{"label":"Size","text":"JCB as a whole reported turnover of £5.7 billion and sales of 113,948 machines in 2025.","source":{"title":"The Construction Index: George Bamford appointed joint chairman of JCB (28 September 2026)","url":"https://www.theconstructionindex.co.uk/news/view/george-bamford-appointed-joint-chairman-of-jcb"}},{"label":"Public roles","text":"Anthony Paul Bamford, Lord Bamford, sat in the House of Lords as a Conservative from 3 October 2013 until he retired on 1 March 2024.","source":{"title":"UK Parliament: Lord Bamford","url":"https://members.parliament.uk/member/4305"}},{"label":"Sector interests","text":"The 2025 accounts list key risks including the availability of raw materials, changing regulations and tariffs, and say tariffs reduced its gross margin in 2025. It has contracts to buy hydrogen from companies controlled by J C E Bamford.","source":{"title":"Companies House: J.C. Bamford Excavators Limited directors' report and financial statements for the year ended 31 December 2025 (filed 2 October 2026)","url":"https://find-and-update.company-information.service.gov.uk/company/00561597/filing-history/MzU0ODMzNjA3MmFkaXF6a2N4/document?format=pdf&download=0"}},{"label":"Official findings","text":"In December 2000 the European Commission fined JCB 39.6 million euros for distribution agreements and practices that broke EU competition rules, including limits on sales between and within countries and on resale prices.","source":{"title":"Concurrences: The EU Commission fines a producer of construction machinery EUR39.6m (December 2000)","url":"https://www.concurrences.com/en/bulletin/news-issues/december-2000/the-eu-commission-fines-a-producer-of-construction-machinery-eur39-6m-for"}}]$df$::jsonb),
  ('jeremy-hosking', 'Jeremy Hosking', 'individual', 9, $df$[{"label":"Who they are","text":"Jeremy Hosking is a multimillionaire fund manager, Brexit supporter and steam train enthusiast.","source":{"title":"The Guardian: Laurence Fox's political party received almost same donations as Lib Dems (3 Jun 2021)","url":"https://www.theguardian.com/politics/2021/jun/03/laurence-foxs-political-party-received-almost-same-donations-as-lib-dems"}},{"label":"Business","text":"Companies House records Jeremy John Hosking as a director of Marathon Asset Management companies from 1996 until he resigned on 11 December 2012, and as a designated member of Hosking Partners LLP since 31 July 2014.","source":{"title":"Companies House: Jeremy John HOSKING personal appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/K4iN0E72aLPCaM_J-zeNG5OwJbc/appointments"}},{"label":"Business","text":"Hosking Partners, established in 2013, describes itself as running a single, unconstrained global equity strategy based on capital cycle analysis; Jeremy Hosking is one of its portfolio managers.","source":{"title":"Hosking Partners: home page","url":"https://www.hoskingpartners.com/"}},{"label":"Business","text":"He is also a director of a group of railway companies, including Locomotive Services Limited (since 2004), Saphos Limited, Statesman Rail Limited and several locomotive owning companies, and of Reclaim the Media Ltd (since 2022).","source":{"title":"Companies House: Jeremy John HOSKING personal appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/K4iN0E72aLPCaM_J-zeNG5OwJbc/appointments"}},{"label":"Business","text":"The Guardian reported in 2019 that he owns a significant share in Crystal Palace FC.","source":{"title":"The Guardian: Tory donor gives £200,000 to Nigel Farage's Brexit party (11 May 2019)","url":"https://www.theguardian.com/politics/2019/may/11/tory-donor-jeremy-hosking-200000-nigel-farage-brexit-party"}},{"label":"Ownership and control","text":"He is the person with significant control of Hosking Partners LLP.","source":{"title":"Companies House: HOSKING PARTNERS LLP persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/OC382151/persons-with-significant-control"}},{"label":"Public roles","text":"In February 2019 he submitted paperwork to form a new party, Brexit Express.","source":{"title":"The Guardian: No-dealers dig in for a fresh battle amid fears of Tory split (17 Feb 2019)","url":"https://www.theguardian.com/politics/2019/feb/17/no-deal-brexiters-tory-split-conservative-multimillionaire-donor-new-party"}},{"label":"Sector interests","text":"The Guardian reported in 2024 that he had more than £100 million invested in fossil fuel interests; he told the paper these investments were made by Hosking Partners LLP on behalf of its institutional clients.","source":{"title":"The Guardian: Who are the wealthy climate sceptics funding rightwing UK politics? (7 Jun 2024)","url":"https://www.theguardian.com/politics/article/2024/jun/07/who-are-the-wealthy-climate-sceptics-funding-rightwing-uk-politics"}},{"label":"Official findings","text":"An arbitration award of October 2014 found that he breached contractual and fiduciary duties he owed to Marathon Asset Management, the investment firm he helped to found. A further award in October 2015 ordered him to pay about £1.38 million in compensation and to return £10,389,957.50 of his profit share. The High Court dismissed his appeal in 2016.","source":{"title":"High Court: Hosking v Marathon Asset Management LLP [2016] EWHC 2418 (Ch)","url":"https://caselaw.nationalarchives.gov.uk/ewhc/ch/2016/2418"}}]$df$::jsonb),
  ('john-gore', 'John Gore', 'individual', 7, $df$[{"label":"Who they are","text":"John Ellis Gore is a British theatre and entertainment producer, educated at Harrow School and the University of London.","source":{"title":"Wikipedia: John Gore (theatre producer)","url":"https://en.wikipedia.org/wiki/John_Gore_(theatre_producer)"}},{"label":"Who they are","text":"The Daily Mirror reported that Companies House listed his country of residence as the Bahamas; he told the paper he is employed by a US company and is tax resident in the US.","source":{"title":"Daily Mirror (via inkl): Boris Johnson's Tories handed £1million by billionaire tycoon based in Bahamas","url":"https://www.inkl.com/news/boris-johnson-s-tories-handed-1million-by-billionaire-tycoon-based-in-bahamas"}},{"label":"Business","text":"He is Chairman and Chief Executive of the John Gore Organization, which describes itself as a leading presenter, distributor and marketer of Broadway theatre. He founded its predecessor, Key Brand Entertainment, in 2004 and it was reorganised as the John Gore Organization in 2016.","source":{"title":"John Gore Organization: Vision and values","url":"https://www.johngore.com/about/vision-and-values/"}},{"label":"Business","text":"In 2023 he acquired Hammer Films and Studios and became its chair and chief executive.","source":{"title":"Hammer Films: Hammer Films acquired by renowned British theatre mogul John Gore (1 Sep 2023)","url":"https://hammerfilms.com/blogs/news/hammer-films-acquired-by-renowned-british-theatre-mogul-john-gore"}},{"label":"Business","text":"In 2020 he bought the Caiseal Mara hotel in Moville, County Donegal, adding to his property interests there.","source":{"title":"The Irish News: Major Tory donor buys arson-hit Co Donegal hotel (24 Jan 2020)","url":"https://www.irishnews.com/news/northernirelandnews/2020/01/24/news/major-tory-donor-buys-arson-hit-co-donegal-hotel-1823426/"}},{"label":"Ownership and control","text":"He is the owner as well as chairman and chief executive of the John Gore Organization, which acquired Broadway Across America from Live Nation in 2008 and Broadway.com in 2010.","source":{"title":"Wikipedia: John Gore (theatre producer)","url":"https://en.wikipedia.org/wiki/John_Gore_(theatre_producer)"}},{"label":"Wealth (as reported)","text":"The Daily Mirror reported in 2019 that he had joined the Sunday Times Rich List that year with an estimated fortune of £1.5 billion.","source":{"title":"Daily Mirror (via inkl): Boris Johnson's Tories handed £1million by billionaire tycoon based in Bahamas","url":"https://www.inkl.com/news/boris-johnson-s-tories-handed-1million-by-billionaire-tycoon-based-in-bahamas"}}]$df$::jsonb),
  ('lord-farmer', 'Lord Farmer', 'individual', 6, $df$[{"label":"Who they are","text":"Michael Stahel Farmer, Lord Farmer, is a metals trader and a current member of the House of Lords, and was Treasurer of the Conservative Party from 2011 to 2015.","source":{"title":"UK Parliament: Lord Farmer, experience","url":"https://members.parliament.uk/member/4321/experience"}},{"label":"Business","text":"He was head of base metal trading at Phibro Salomon from 1987 to 1989, chief executive of The Metal & Commodity Company from 1989 to 1999, a managing director at MG plc from 1999 to 2000 and at Enron Europe from 2000 to 2001, and senior partner of RK Capital Management from 2005 to 2024.","source":{"title":"UK Parliament: Lord Farmer, experience","url":"https://members.parliament.uk/member/4321/experience"}},{"label":"Ownership and control","text":"Companies House lists him as a current director of Trinipol Ltd (since October 2024), FHN Holding Limited (since March 2023) and The Cross Trust (since April 2008), and as a former director of The Conservative Party Foundation Limited from December 2015 to February 2024.","source":{"title":"Companies House: Michael Stahel FARMER appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/gLj153rXkxrp2d8Hn2WCy_RqYFk/appointments"}},{"label":"Public roles","text":"He was Treasurer of the Conservative Party from 2011 to 2015 and a director and trustee of the Conservative Foundation from 2016 to 2023, and has chaired the Family Hubs Network since 2020.","source":{"title":"UK Parliament: Lord Farmer, experience","url":"https://members.parliament.uk/member/4321/experience"}},{"label":"Public roles","text":"He led a review for the Ministry of Justice, published on 10 August 2017, on the importance of strengthening prisoners' family ties to prevent reoffending and reduce intergenerational crime.","source":{"title":"GOV.UK: Importance of strengthening prisoners' family ties to prevent reoffending and reduce intergenerational crime (10 August 2017)","url":"https://www.gov.uk/government/publications/importance-of-strengthening-prisoners-family-ties-to-prevent-reoffending-and-reduce-intergenerational-crime"}},{"label":"Honours","text":"He was created a life peer as Baron Farmer, of Bishopsgate, on 5 September 2014 and sits on the Conservative benches.","source":{"title":"Wikipedia: Michael Farmer, Baron Farmer","url":"https://en.wikipedia.org/wiki/Michael_Farmer,_Baron_Farmer"}}]$df$::jsonb),
  ('lord-sainsbury-of-preston-candover', 'Lord Sainsbury of Preston Candover', 'individual', 5, $df$[{"label":"Who they are","text":"John Davan Sainsbury, Lord Sainsbury of Preston Candover, was a former chairman of Sainsbury's and a Conservative member of the House of Lords from 31 January 1989 until his death in January 2022.","source":{"title":"UK Parliament: Lord Sainsbury of Preston Candover","url":"https://members.parliament.uk/member/2162"}},{"label":"Business","text":"He joined Sainsbury's in 1950, became a director in 1958 and deputy chairman in 1967, and was chairman and chief executive from 1969 until he retired in 1992, after which he was life president of the company.","source":{"title":"Wikipedia: John Sainsbury, Baron Sainsbury of Preston Candover","url":"https://en.wikipedia.org/wiki/John_Sainsbury,_Baron_Sainsbury_of_Preston_Candover"}},{"label":"Business","text":"With his wife, Lady Anya Sainsbury, he founded the Linbury Trust in the early 1970s, which funds the arts, education, homelessness and overseas aid.","source":{"title":"The Daily Telegraph via PressReader: Lord Sainsbury of Preston Candover dies at 94 (15 January 2022)","url":"https://www.pressreader.com/uk/the-daily-telegraph/20220115/282415582648669"}},{"label":"Public roles","text":"He sat as a Conservative peer in the House of Lords from 1989 to 2022.","source":{"title":"UK Parliament: Lord Sainsbury of Preston Candover","url":"https://members.parliament.uk/member/2162"}},{"label":"Honours","text":"He was knighted in 1980 for services to food retailing, made a life peer in 1989 and made a Knight of the Garter in 1992.","source":{"title":"The Daily Telegraph via PressReader: Lord Sainsbury of Preston Candover dies at 94 (15 January 2022)","url":"https://www.pressreader.com/uk/the-daily-telegraph/20220115/282415582648669"}}]$df$::jsonb),
  ('lord-sainsbury-of-turville', 'Lord Sainsbury of Turville', 'individual', 8, $df$[{"label":"Who they are","text":"David John Sainsbury, Lord Sainsbury of Turville, is a former chairman of J Sainsbury plc and a former Labour member of the House of Lords, who retired from the House on 1 July 2021.","source":{"title":"UK Parliament: Lord Sainsbury of Turville","url":"https://members.parliament.uk/member/2161"}},{"label":"Business","text":"He joined J Sainsbury plc in 1963 and was its finance director from 1973 to 1990, deputy chairman from 1988 to 1992 and chairman from 1992 to 1998.","source":{"title":"David Sainsbury: Biography","url":"https://davidsainsbury.org.uk/biography"}},{"label":"Business","text":"He set up the Gatsby Charitable Foundation as an endowed grant making trust in 1967.","source":{"title":"Gatsby Charitable Foundation: David Sainsbury","url":"https://gatsby.org.uk/about-gatsby/david-sainsbury"}},{"label":"Business","text":"He founded and chairs the Institute for Government.","source":{"title":"David Sainsbury: Biography","url":"https://davidsainsbury.org.uk/biography"}},{"label":"Public roles","text":"He was a Labour member of the House of Lords from 3 October 1997 to 1 July 2021, and a Parliamentary Under Secretary for science and innovation at the Department of Trade and Industry from 1998 to November 2006.","source":{"title":"UK Parliament: Lord Sainsbury of Turville","url":"https://members.parliament.uk/member/2161"}},{"label":"Public roles","text":"As science minister his responsibilities covered science and technology, innovation, space, the bioscience and chemical industries, and the Patent Office.","source":{"title":"Gatsby Charitable Foundation: David Sainsbury","url":"https://gatsby.org.uk/about-gatsby/david-sainsbury"}},{"label":"Public roles","text":"He was elected Chancellor of the University of Cambridge in October 2011.","source":{"title":"David Sainsbury: Biography","url":"https://davidsainsbury.org.uk/biography"}},{"label":"Honours","text":"He became a life peer, Lord Sainsbury of Turville, in October 1997.","source":{"title":"David Sainsbury: Biography","url":"https://davidsainsbury.org.uk/biography"}}]$df$::jsonb),
  ('martin-taylor', 'Martin Taylor', 'individual', 5, $df$[{"label":"Who they are","text":"Martin Taylor is a London hedge fund manager who in 2015 helped run Nevsky Capital, a hedge fund based in Mayfair, and was identified as a major Labour donor.","source":{"title":"The Bureau of Investigative Journalism: Labour's mystery £600k donor Martin Taylor revealed as Mayfair hedge funder (20 March 2015)","url":"https://www.thebureauinvestigates.com/stories/2015-03-20/labours-mystery-600k-donor-martin-taylor-revealed-as-mayfair-hedge-funder"}},{"label":"Business","text":"Martin Edward Taylor was a designated member of Nevsky Capital LLP from December 2006; the partnership was dissolved in July 2019.","source":{"title":"Companies House: NEVSKY CAPITAL LLP (OC320343) officers","url":"https://find-and-update.company-information.service.gov.uk/company/OC320343/officers"}},{"label":"Business","text":"The Nevsky fund previously held significant stakes in the Russian energy companies Gazprom and Lukoil; the Bureau noted the stakes were controlled by Nevsky Capital, not by Taylor himself.","source":{"title":"The Bureau of Investigative Journalism: Labour's mystery £600k donor Martin Taylor revealed as Mayfair hedge funder (20 March 2015)","url":"https://www.thebureauinvestigates.com/stories/2015-03-20/labours-mystery-600k-donor-martin-taylor-revealed-as-mayfair-hedge-funder"}},{"label":"Business","text":"His new hedge fund firm, Crake Asset Management, started trading on 1 October 2019 after raising $1.6 billion.","source":{"title":"Daily Alts: Martin Taylor's new hedge fund Crake Asset Management (8 October 2019)","url":"https://dailyalts.com/martin-taylor-new-hedge-fund-crake-asset-management/"}},{"label":"Ownership and control","text":"Companies House lists Mr Martin Edward Taylor as the person with significant control of Crake Asset Management LLP since May 2018, holding more than 50 per cent but less than 75 per cent of voting rights and 75 per cent or more of the right to surplus assets.","source":{"title":"Companies House: CRAKE ASSET MANAGEMENT LLP (OC422582) persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/OC422582/persons-with-significant-control"}}]$df$::jsonb),
  ('mohamed-mansour', 'Sir Mohamed Mansour', 'individual', 9, $df$[{"label":"Who they are","text":"Sir Mohamed Mansour is an Egyptian born billionaire businessman and former Egyptian transport minister who was appointed senior treasurer of the Conservative Party in December 2022.","source":{"title":"The Guardian: Tories make billionaire ex-Mubarak minister senior treasurer (14 December 2022)","url":"https://www.theguardian.com/politics/2022/dec/14/tories-billionaire-murbarak-minister-mohamed-mansour-party-senior-treasurer-mohamed-mansour-egypt"}},{"label":"Business","text":"The Press Association described him in March 2024 as chairman of the Mansour Group of businesses.","source":{"title":"Express & Star (PA): Largest donations accepted by Conservatives from individuals since January 2023 (13 March 2024)","url":"https://expressandstar.com/news/uk-news/2024/03/13/largest-donations-accepted-by-conservatives-from-individuals-since-january-2023"}},{"label":"Business","text":"Forbes says he oversees the Mansour Group, a family conglomerate founded by his father in 1952 with about 60,000 employees; he holds Egyptian and UK citizenship and lives in London.","source":{"title":"Forbes: Mohamed Mansour profile (real time net worth, 31 October 2026)","url":"https://www.forbes.com/profile/mohamed-mansour/"}},{"label":"Business","text":"The Mansour Group says it has worked with General Motors, Caterpillar, Caffe Nero and McDonald's, and its activities include automotive dealing, real estate development, infrastructure equipment and food service; its investment arm Man Capital invests in sports, education, hospitality, technology, healthcare and renewable energy.","source":{"title":"Mansour Group: home page","url":"https://www.mansourgroup.com/"}},{"label":"Ownership and control","text":"The Guardian described Unatrac as his company and reported in December 2022 that it had donated more than £600,000 to the Conservative Party; he is the founder of the family owned investment firm Man Capital.","source":{"title":"The Guardian: Tories make billionaire ex-Mubarak minister senior treasurer (14 December 2022)","url":"https://www.theguardian.com/politics/2022/dec/14/tories-billionaire-murbarak-minister-mohamed-mansour-party-senior-treasurer-mohamed-mansour-egypt"}},{"label":"Wealth (as reported)","text":"Forbes estimated his net worth at $4 billion on 31 October 2026.","source":{"title":"Forbes: Mohamed Mansour profile (real time net worth, 31 October 2026)","url":"https://www.forbes.com/profile/mohamed-mansour/"}},{"label":"Public roles","text":"He served as Egypt's transport minister under President Hosni Mubarak until 2009, and in 2021 was given a role on the UK government's investment advisory council as founder of Man Capital.","source":{"title":"The Guardian: Tories make billionaire ex-Mubarak minister senior treasurer (14 December 2022)","url":"https://www.theguardian.com/politics/2022/dec/14/tories-billionaire-murbarak-minister-mohamed-mansour-party-senior-treasurer-mohamed-mansour-egypt"}},{"label":"Public roles","text":"Rishi Sunak announced in December 2022 that he would be senior treasurer of the Conservative Party, a fundraising role.","source":{"title":"The Guardian: Tories make billionaire ex-Mubarak minister senior treasurer (14 December 2022)","url":"https://www.theguardian.com/politics/2022/dec/14/tories-billionaire-murbarak-minister-mohamed-mansour-party-senior-treasurer-mohamed-mansour-egypt"}},{"label":"Honours","text":"He was made a Knight Bachelor in 2024 as a businessman, philanthropist and Senior Treasurer of the Conservative Party.","source":{"title":"The London Gazette: Honours and Awards, Knights Bachelor (Issue 64374, 19 April 2024)","url":"https://www.thegazette.co.uk/notice/4603787"}}]$df$::jsonb),
  ('national-conservative-draws-society', 'National Conservative Draws Society', 'society', 4, $df$[{"label":"Who they are","text":"The National Conservative Draws Society promotes the Conservative Lottery and the seasonal Superdraws. It describes itself as independent of the Conservative Party and says it donates all its profits to the party.","source":{"title":"Conservative Lottery: The Rules of the Lottery","url":"https://lottery.conservatives.com/draw/terms-conditions"}},{"label":"Business","text":"It holds Gambling Commission society lottery licences, non remote since 13 August 2009 and remote since 21 September 2016, under account number 5027, with its head office at 1 Norfolk Row, London SE1.","source":{"title":"Gambling Commission public register: National Conservative Draws Society (account 5027)","url":"https://www.gamblingcommission.gov.uk/public-register/business/detail/5027"}},{"label":"Size","text":"The lottery says that in 2025 it donated 69.19 per cent of ticket sales money to the Conservative Party, £624,267.45.","source":{"title":"Conservative Lottery: How do I play? (FAQ)","url":"https://lottery.conservatives.com/draw/faq"}},{"label":"Represents","text":"Entry to the lottery is open to residents of mainland Great Britain and Northern Ireland aged 18 or over.","source":{"title":"Conservative Lottery: The Rules of the Lottery","url":"https://lottery.conservatives.com/draw/terms-conditions"}}]$df$::jsonb),
  ('peter-hargreaves', 'Peter Hargreaves', 'individual', 6, $df$[{"label":"Who they are","text":"Peter Hargreaves is the co founder of the investment firm Hargreaves Lansdown, which he started with Stephen Lansdown in 1981 from the spare bedroom of his house in Bristol.","source":{"title":"The Guardian via Yahoo Finance: Millions for charity and Brexit: inside Peter Hargreaves's world (1 February 2020)","url":"https://uk.finance.yahoo.com/news/millions-charity-brexit-inside-peter-160018225.html"}},{"label":"Business","text":"Companies House records Peter Kendal Hargreaves as a director of Hargreaves Lansdown companies until 14 April 2015, a director of ITM Power plc from 2004 to 2017, and a director of Hargreaves Lansdown Group Limited from 24 April 2025 to 24 September 2025.","source":{"title":"Companies House: Peter Kendal HARGREAVES appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/5UekpLTeAtde-jBvNQ1njgctdHU/appointments"}},{"label":"Ownership and control","text":"He is a designated member of Blue Whale Capital LLP, appointed on 10 February 2017, his only active appointment on the Companies House register.","source":{"title":"Companies House: Peter Kendal HARGREAVES appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/5UekpLTeAtde-jBvNQ1njgctdHU/appointments"}},{"label":"Ownership and control","text":"The Guardian reported in February 2020 that he owned one third of Hargreaves Lansdown.","source":{"title":"The Guardian via Yahoo Finance: Millions for charity and Brexit: inside Peter Hargreaves's world (1 February 2020)","url":"https://uk.finance.yahoo.com/news/millions-charity-brexit-inside-peter-160018225.html"}},{"label":"Wealth (as reported)","text":"The Sunday Times Rich List 2018 estimated his wealth at £3.2 billion, ranking him 42nd, as reported by Professional Adviser.","source":{"title":"Professional Adviser: Rich List: Peter Hargreaves into top 50; Odey's wealth falls £25m (14 May 2018)","url":"https://www.professionaladviser.com/news/3032193/rich-list-peter-hargreaves-odeys-wealth-falls-gbp25m"}},{"label":"Honours","text":"He was appointed CBE in the 2014 New Year Honours.","source":{"title":"Wikipedia: Peter Hargreaves","url":"https://en.wikipedia.org/wiki/Peter_Hargreaves"}}]$df$::jsonb),
  ('quadrature-capital', 'Quadrature Capital Limited', 'company', 7, $df$[{"label":"Who they are","text":"Quadrature Capital Limited is a private limited company registered in London (company number 09516131), incorporated on 28 March 2015, whose nature of business is fund management activities.","source":{"title":"Companies House: QUADRATURE CAPITAL LIMITED overview","url":"https://find-and-update.company-information.service.gov.uk/company/09516131"}},{"label":"Business","text":"Quadrature describes itself as a systematic trading firm founded by programmers in 2010 that builds automated trading systems to trade its own proprietary capital.","source":{"title":"Quadrature: home page","url":"https://www.quadrature.ai/"}},{"label":"Business","text":"Its accounts give its principal activity as the provision of investment management services, with revenue driven by the performance and assets of the funds it manages. After the year to January 2026 it told the Financial Conduct Authority and the US Securities and Exchange Commission that it intended to withdraw its permissions as an Alternative Investment Fund Manager.","source":{"title":"Companies House: Quadrature Capital Limited full accounts made up to 31 January 2026 (filed 22 Oct 2026)","url":"https://find-and-update.company-information.service.gov.uk/company/09516131/filing-history/MzU1MjMzNDk5M2FkaXF6a2N4/document?format=pdf&download=0"}},{"label":"Business","text":"Quadrature Capital Limited set up the Quadrature Charitable Foundation in 2019; its focus areas include climate risk, human security, and poverty and inequality.","source":{"title":"Quadrature: home page","url":"https://www.quadrature.ai/"}},{"label":"Ownership and control","text":"Greg Howard Skinner and Suneil Setiya are its persons with significant control, each owning more than 25 per cent but not more than 50 per cent of the shares, and both have been directors since 28 March 2015.","source":{"title":"Companies House: QUADRATURE CAPITAL LIMITED persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/09516131/persons-with-significant-control"}},{"label":"Ownership and control","text":"Its immediate parent is QC Ventures Limited, incorporated in the Cayman Islands. The accounts say the company is jointly controlled by G H Skinner and S Setiya through their holding companies, Squad Holdings Limited and Alethia Holdings Limited.","source":{"title":"Companies House: Quadrature Capital Limited full accounts made up to 31 January 2026 (filed 22 Oct 2026)","url":"https://find-and-update.company-information.service.gov.uk/company/09516131/filing-history/MzU1MjMzNDk5M2FkaXF6a2N4/document?format=pdf&download=0"}},{"label":"Size","text":"In the year to 31 January 2026 it reported turnover of £2,203.5 million (2025: £1,224.8 million), profit before tax of £975.2 million and an average of 169 employees including directors.","source":{"title":"Companies House: Quadrature Capital Limited full accounts made up to 31 January 2026 (filed 22 Oct 2026)","url":"https://find-and-update.company-information.service.gov.uk/company/09516131/filing-history/MzU1MjMzNDk5M2FkaXF6a2N4/document?format=pdf&download=0"}}]$df$::jsonb),
  ('sir-michael-davis', 'Sir Mick Davis', 'individual', 9, $df$[{"label":"Who they are","text":"Sir Mick Davis is a South African born businessman and philanthropist who made his money in mining and was chief executive of the Conservative Party until July 2019.","source":{"title":"Jewish News: Sir Mick Davis resigns as chief executive of the Conservative Party (24 July 2019)","url":"https://www.jewishnews.co.uk/sir-mick-davis-resigns-as-chief-executive-of-the-conservative-party/"}},{"label":"Business","text":"He was chief financial officer and an executive director of Billiton from 1997, and chief executive of Xstrata from 2001 until Glencore took it over in 2013; he later formed the mining venture X2 Resources.","source":{"title":"SA Jewish Report: Mick Davis calls for greater Tory funding on quitting his post (25 July 2019)","url":"https://sajr.co.za/mick-davis-calls-for-greater-tory-funding-on-quitting-his-post"}},{"label":"Business","text":"He is chief executive of Vision Blue Resources, which takes stakes in companies working in graphite, vanadium, silicon metal, tin and rare earths and has raised more than $650 million.","source":{"title":"E&MJ: Vision Blue Resources raises $650M","url":"https://www.e-mj.com/leading-developments/vision-blue-resources-raises-650m/"}},{"label":"Ownership and control","text":"Companies House lists Sir Michael Lawrence Davis as a current officer of Vision Blue Advisors UK LLP (since June 2021), Macsteel Global Limited (since November 2023) and UK Onward Thinktank Ltd (since March 2020).","source":{"title":"Companies House: Sir Michael Lawrence DAVIS appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/6UITUSZQsNbEaNtxNfctbsM2SvA/appointments"}},{"label":"Wealth (as reported)","text":"The Guardian reported in April 2013 that he would leave Xstrata with nearly £75m, made up of cash payments, share options and shares sold the previous December.","source":{"title":"The Guardian: Mick Davis departs Xstrata with nearly £75m (16 April 2013)","url":"https://www.theguardian.com/business/2013/apr/16/mick-davis-leaves-xstrata-with-75m"}},{"label":"Public roles","text":"He became Conservative Party treasurer in 2016 and was also appointed the party's chief executive in June 2017.","source":{"title":"Jewish News: Former JLC chair Sir Mick Davis made Conservative Party CEO (27 June 2017)","url":"https://www.jewishnews.co.uk/former-jlc-chair-sir-mick-davis-made-conservative-party-ceo/amp/"}},{"label":"Public roles","text":"He resigned as chief executive and treasurer of the Conservative Party in July 2019.","source":{"title":"SA Jewish Report: Mick Davis calls for greater Tory funding on quitting his post (25 July 2019)","url":"https://sajr.co.za/mick-davis-calls-for-greater-tory-funding-on-quitting-his-post"}},{"label":"Public roles","text":"He chaired the Prime Minister's Holocaust Commission and was formerly chair of the Jewish Leadership Council.","source":{"title":"Jewish News: Former JLC chair Sir Mick Davis made Conservative Party CEO (27 June 2017)","url":"https://www.jewishnews.co.uk/former-jlc-chair-sir-mick-davis-made-conservative-party-ceo/amp/"}},{"label":"Honours","text":"He was made a Knight Bachelor in the 2015 Birthday Honours, as Chair of the Prime Minister's Holocaust Commission, for services to Holocaust commemoration and education.","source":{"title":"The London Gazette: Birthday Honours 2015, Knights Bachelor (Issue 61256, 13 June 2015)","url":"https://www.thegazette.co.uk/London/issue/61256/supplement/B2/data.pdf"}}]$df$::jsonb),
  ('the-phoenix-partnership', 'The Phoenix Partnership (Leeds) Ltd (TPP)', 'company', 10, $df$[{"label":"Who they are","text":"The Phoenix Partnership (Leeds) Ltd is a private limited company, number 04077829, incorporated on 25 September 2000 with its registered office in Horsforth, Leeds.","source":{"title":"Companies House: THE PHOENIX PARTNERSHIP (LEEDS) LTD (04077829) overview","url":"https://find-and-update.company-information.service.gov.uk/company/04077829"}},{"label":"Business","text":"Its 2025 accounts give its principal activity as the provision of computer software and support to the health sector. Companies House lists its nature of business as business and domestic software development and information technology consultancy.","source":{"title":"Companies House: The Phoenix Partnership (Leeds) Limited full accounts made up to 31 March 2025 (filed 4 December 2025)","url":"https://find-and-update.company-information.service.gov.uk/company/04077829/filing-history/MzQ5MTkyNTM3MWFkaXF6a2N4/document?format=pdf&download=0"}},{"label":"Business","text":"TPP describes itself as a provider of healthcare technology whose core product, SystmOne, provides a shared electronic health record. It says it was founded in 1997 by Frank Hester OBE.","source":{"title":"TPP: About us","url":"https://tpp-uk.com/about-us/"}},{"label":"Ownership and control","text":"Companies House lists TPP Finance Limited as its person with significant control, holding 75 per cent or more of its shares and votes. Francis Xavier James Hester was also listed, with the right to appoint or remove directors, until 5 September 2025.","source":{"title":"Companies House: THE PHOENIX PARTNERSHIP (LEEDS) LTD persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/04077829/persons-with-significant-control"}},{"label":"Ownership and control","text":"TPP Finance Limited is in turn controlled by TPPH (Leeds) Limited, which holds 75 per cent or more of its shares and votes.","source":{"title":"Companies House: TPP FINANCE LIMITED persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/08892232/persons-with-significant-control"}},{"label":"Ownership and control","text":"TPPH (Leeds) Limited is controlled by TPP Group Limited, which holds 75 per cent or more of its shares and votes.","source":{"title":"Companies House: TPPH (LEEDS) LIMITED persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/08919675/persons-with-significant-control"}},{"label":"Ownership and control","text":"Companies House lists Francis Xavier James Hester as the person with significant control of TPP Group Limited, holding 75 per cent or more of its shares and votes, notified on 24 January 2019.","source":{"title":"Companies House: TPP GROUP LIMITED persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/11785575/persons-with-significant-control"}},{"label":"Ownership and control","text":"Francis Xavier James Hester was a director from 21 February 2001 until 5 September 2025. Maria Tomasso has been a director since 5 September 2025.","source":{"title":"Companies House: THE PHOENIX PARTNERSHIP (LEEDS) LTD officers","url":"https://find-and-update.company-information.service.gov.uk/company/04077829/officers"}},{"label":"Size","text":"In the year to 31 March 2025 the company had turnover of £97.1 million (2024: £86.0 million) and profit before tax of £47.5 million. Its average staff numbers fell from 91 to 76.","source":{"title":"Companies House: The Phoenix Partnership (Leeds) Limited full accounts made up to 31 March 2025 (filed 4 December 2025)","url":"https://find-and-update.company-information.service.gov.uk/company/04077829/filing-history/MzQ5MTkyNTM3MWFkaXF6a2N4/document?format=pdf&download=0"}},{"label":"Sector interests","text":"TPP says SystmOne provides clinical IT services in over 25 care settings, including more than 2,600 GP practices and a third of acute mental health trusts, and that it works alongside governments. It reports deployments outside the UK in China, the Middle East and the Caribbean.","source":{"title":"TPP: About us","url":"https://tpp-uk.com/about-us/"}}]$df$::jsonb),
  ('unison', 'UNISON', 'union', 5, $df$[{"label":"Who they are","text":"UNISON is a trade union which describes itself as the largest union in the UK.","source":{"title":"UNISON: About UNISON","url":"https://www.unison.org.uk/about/"}},{"label":"Size","text":"UNISON reported 1,465,358 members at 31 December 2025 in its annual return to the Certification Officer, of whom 1,410,095 were in Great Britain and 55,263 in Northern Ireland. The return names Christina McAnea as general secretary to 21 January 2026 and Andrea Egan from 22 January 2026.","source":{"title":"Certification Officer (GOV.UK): UNISON: The Public Service Union 2025 Annual Return (form AR21, year ended 31 December 2025)","url":"https://assets.publishing.service.gov.uk/media/6a7b0f44423b0bdba0290ec0/AR21_2025.pdf"}},{"label":"Represents","text":"UNISON says it represents members in local government, health, education and outsourced services across England, Wales, Scotland and Northern Ireland.","source":{"title":"UNISON: About UNISON","url":"https://www.unison.org.uk/about/"}},{"label":"Political fund","text":"In 2025 UNISON's political fund had income of £6.736 million and spending of £4.858 million, and held £20.216 million at the end of the year. 1,235,989 members contributed to the fund.","source":{"title":"Certification Officer (GOV.UK): UNISON: The Public Service Union 2025 Annual Return (form AR21, year ended 31 December 2025)","url":"https://assets.publishing.service.gov.uk/media/6a7b0f44423b0bdba0290ec0/AR21_2025.pdf"}},{"label":"Political fund","text":"UNISON is one of the 11 trade unions affiliated to the Labour Party.","source":{"title":"The Labour Party: Affiliated Unions","url":"https://labour.org.uk/people/unions/"}}]$df$::jsonb),
  ('unite-the-union', 'Unite the Union', 'union', 7, $df$[{"label":"Who they are","text":"Unite the Union is a trade union which describes itself as Britain and Ireland's biggest union. Its general secretary is Sharon Graham.","source":{"title":"Unite the Union: Who we are","url":"https://www.unitetheunion.org/who-we-are"}},{"label":"Who they are","text":"Unite was formed in May 2007 when Amicus merged with the Transport and General Workers Union (TGWU), so Amicus and the TGWU are its predecessor unions.","source":{"title":"Unite the Union: History","url":"https://www.unitetheunion.org/who-we-are/history"}},{"label":"Size","text":"Unite reported 1,177,292 members at 31 December 2023 in its annual return to the Certification Officer, of whom 1,103,160 were in Great Britain. This was a partial return containing only the non financial elements.","source":{"title":"Certification Officer (GOV.UK): Unite the Union Partial 2023 Annual Return (year ended 31 December 2023)","url":"https://assets.publishing.service.gov.uk/media/680a49b57a11df940be1aab7/Partial_AR21_2023.pdf"}},{"label":"Represents","text":"Its history page says the TGWU drew its members from the dock, road transport and inland waterway industries, and that Amicus had significant membership in engineering and the health service.","source":{"title":"Unite the Union: History","url":"https://www.unitetheunion.org/who-we-are/history"}},{"label":"Political fund","text":"In 2020, the latest year for which a full return with accounts is published, Unite's political fund had income of £6.767 million and spending of £2.681 million, and held £20.548 million at the end of the year. 867,458 members contributed to the fund.","source":{"title":"Certification Officer (GOV.UK): Unite the Union 2020 Annual Return (form AR21, year ended 31 December 2020)","url":"https://assets.publishing.service.gov.uk/media/61b09cf1e90e0704478a9e5b/795T_2020.pdf"}},{"label":"Political fund","text":"Unite is one of the 11 trade unions affiliated to the Labour Party.","source":{"title":"The Labour Party: Affiliated Unions","url":"https://labour.org.uk/people/unions/"}},{"label":"Official findings","text":"In August 2026 the Certification Officer found that in 2021 Unite failed to keep a satisfactory system of control over its accounting records, cash, receipts and remittances, in breach of trade union law. The inspector found no refusal or wilful neglect, so there was no prosecution; the Certification Officer took no further action except to require Unite to report when its remedial work is complete.","source":{"title":"Certification Officer: Financial irregularity decision, Unite the Union (August 2026)","url":"https://www.gov.uk/government/publications/financial-irregularity-decision-unite-the-union"}}]$df$::jsonb),
  ('usdaw', 'Usdaw (Union of Shop, Distributive and Allied Workers)', 'union', 5, $df$[{"label":"Who they are","text":"The Union of Shop, Distributive and Allied Workers (Usdaw) is a trade union with its head office at Furness Quay, Salford. Its annual return for 2025 names Joanne Thomas as general secretary.","source":{"title":"Certification Officer (GOV.UK): Union of Shop, Distributive & Allied Workers 2025 Annual Return (form AR21, year ended 31 December 2025)","url":"https://assets.publishing.service.gov.uk/media/6a7b10e1aadaaddf89b6e411/AR21_2025.pdf"}},{"label":"Size","text":"Usdaw reported 372,499 members at 31 December 2025 in its annual return to the Certification Officer, of whom 358,569 were in Great Britain and 13,930 in Northern Ireland.","source":{"title":"Certification Officer (GOV.UK): Union of Shop, Distributive & Allied Workers 2025 Annual Return (form AR21, year ended 31 December 2025)","url":"https://assets.publishing.service.gov.uk/media/6a7b10e1aadaaddf89b6e411/AR21_2025.pdf"}},{"label":"Represents","text":"Usdaw says its members work for all major retailers and in road transport, warehouses and distribution, food manufacturing, dairies, pharmaceuticals and home shopping, among other industries.","source":{"title":"Usdaw: About Usdaw","url":"https://www.usdaw.org.uk/about-usdaw/"}},{"label":"Political fund","text":"In 2025 Usdaw's political fund had income of £1.489 million and spending of £1.181 million, and held £591,000 at the end of the year. 288,416 members contributed to the fund.","source":{"title":"Certification Officer (GOV.UK): Union of Shop, Distributive & Allied Workers 2025 Annual Return (form AR21, year ended 31 December 2025)","url":"https://assets.publishing.service.gov.uk/media/6a7b10e1aadaaddf89b6e411/AR21_2025.pdf"}},{"label":"Political fund","text":"Usdaw is one of the 11 trade unions affiliated to the Labour Party.","source":{"title":"The Labour Party: Affiliated Unions","url":"https://labour.org.uk/people/unions/"}}]$df$::jsonb);

