DO $$
DECLARE
  profiles integer; slug_rows integer; fact_total integer; matching integer; pd_n bigint; pd_h text; before_n bigint; before_h text;
BEGIN
  SELECT count(*) INTO profiles FROM public.donor_profiles;
  SELECT count(*) INTO slug_rows FROM public.donor_profile_slugs;
  SELECT sum(jsonb_array_length(facts)) INTO fact_total FROM public.donor_profiles;
  SELECT count(*) INTO matching FROM public.donor_profiles p JOIN dp_file f USING (key)
   WHERE p.facts = f.facts AND p.name = f.name AND p.kind = f.kind AND jsonb_array_length(p.facts) = f.n AND p.last_checked = DATE '2026-10-31';
  SELECT count(*), md5(string_agg(id::text, ',' ORDER BY id)) INTO pd_n, pd_h FROM public.political_donations;
  SELECT n, h INTO before_n, before_h FROM pd_before;
  RAISE NOTICE 'profiles %, slugs %, facts %, profiles matching the file %, political_donations rows % (unchanged %)',
    profiles, slug_rows, fact_total, matching, pd_n, (pd_n = before_n AND pd_h = before_h);
  IF profiles <> 25 THEN RAISE EXCEPTION 'expected 25 profiles, got %', profiles; END IF;
  IF slug_rows <> 41 THEN RAISE EXCEPTION 'expected 41 slugs, got %', slug_rows; END IF;
  IF fact_total <> 172 THEN RAISE EXCEPTION 'expected 172 facts, got %', fact_total; END IF;
  IF matching <> 25 THEN RAISE EXCEPTION 'expected 25 profiles equal to the file, got %', matching; END IF;
  IF pd_n IS DISTINCT FROM before_n OR pd_h IS DISTINCT FROM before_h THEN RAISE EXCEPTION 'political_donations changed'; END IF;
  IF has_table_privilege('anon', 'public.donor_profiles', 'SELECT') OR has_table_privilege('authenticated', 'public.donor_profiles', 'SELECT')
     OR has_table_privilege('anon', 'public.donor_profile_slugs', 'SELECT') OR has_table_privilege('authenticated', 'public.donor_profile_slugs', 'SELECT') THEN
    RAISE EXCEPTION 'anon or authenticated can read the new tables';
  END IF;
  IF NOT has_table_privilege('service_role', 'public.donor_profiles', 'SELECT') OR NOT has_table_privilege('service_role', 'public.donor_profile_slugs', 'SELECT') THEN
    RAISE EXCEPTION 'service_role cannot read the new tables';
  END IF;
  IF has_table_privilege('service_role', 'public.donor_profiles', 'INSERT,UPDATE,DELETE') OR has_table_privilege('service_role', 'public.donor_profile_slugs', 'INSERT,UPDATE,DELETE') THEN
    RAISE EXCEPTION 'service_role can write the new tables';
  END IF;
END $$;

COMMIT;
